<script setup lang="ts">
import { computed, nextTick, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute, useRouter, onBeforeRouteLeave } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, apiPage, mutation } from '../api/client'
import StudyTutor from '../components/StudyTutor.vue'
import StudyPracticePanel from '../components/StudyPracticePanel.vue'
import type { StudyTrack } from '../types/study'
import RunPanel from '../components/RunPanel.vue'
import LocalProjectIde from '../components/LocalProjectIde.vue'
import PlanningView from './PlanningView.vue'
import PracticeCard, { type Practice } from '../components/PracticeCard.vue'
import PracticeDelivery from '../components/PracticeDelivery.vue'
import KnowledgeSearch from '../components/KnowledgeSearch.vue'
import LearningExplanation, { type LearningPoint, type LearningReport } from '../components/LearningExplanation.vue'
type Objective={objective_version_id:string;title:string;target_behavior:string;deliverables:string[]}
type Plan={plan_id:string;plan_version_id:string;version:number;kind:string;objectives:Objective[]}
type Unit={learning_unit_id:string;objective_version_id:string;selection_id:string;commit:string;reading_steps:{step_id:string;title:string;why:string;citation_ids:string[];questions:string[]}[];progress:{version:number;completed_step_ids:string[];note?:string;actual_minutes?:number|null};why_this_unit:string}
type Selection={selection_id:string;repository_snapshot_id:string}
type Citation={citation_id:string;repository_snapshot_id:string;path:string;start_line:number;end_line:number;quote:string;commit:string}
type RepoFile={path:string;line_count:number}
type Edit={path:string;before:string|null;after:string|null;reason:string}
type Action=LearningReport & Practice & {command_id?:string;practice_id?:string;answer?:string;instruction?:string;edits?:Edit[];argv?:string[];reason?:string;stdout?:string;stderr?:string;exit_code?:number;error?:string;citation_ids?:string[]}
type Workspace={study_attempt?:{help_mode:string;attempt_id:string;practice_id:string;ended_at:string|null};links?:{objective_version_id:string;citation_id:string;path:string;start_line:number;end_line:number}[];workspace_id:string;name:string;revision:number;files:Record<string,string>;actions:Action[]}
const route=useRoute(),router=useRouter(),write=mutation()
const desktop=!!(window as unknown as {__TAURI__?:unknown}).__TAURI__
const storage=ref(desktop?'local':'copy'),localIde=ref<InstanceType<typeof LocalProjectIde>|null>(null)
const localConnected=computed(()=>localIde.value?.connected??false)
const usePlan=ref(!!route.query.objective)
const requirementSources=ref<{source_id:string;title:string|null;read_status:string;source_type:string}[]>([]),sourceIds=ref<string[]>([]),incomingSources=ref<string[]>(typeof route.query.source==='string'?[route.query.source]:Array.isArray(route.query.source)?route.query.source.filter((s):s is string=>typeof s==='string'):[])
async function switchStorage(value:string|number|boolean|undefined){if(!await canLeave())return;if(value==='copy')await localIde.value?.disconnect();storage.value=String(value)}
async function bindLocal(id:string){await openWorkspace(id,false);const bound=workspace.value?.study_attempt?.practice_id;const item=workspace.value?.actions.find(a=>a.id===bound);if(item)await resumePractice(item);mode.value='ide'}
async function syncLocal(id:string){if(workspaceId.value===id)workspace.value=await api<Workspace>('/studio/workspaces/'+id)}
async function resolveSources(){if(incomingSources.value.length){return incomingSources.value.slice()}return Promise.all(sourceIds.value.map(async id=>{const row=await api<{snapshots:{source_snapshot_id:string;version_no:number}[]}>('/sources/'+id);const latest=row.snapshots.slice().sort((a,b)=>b.version_no-a.version_no)[0];if(!latest)throw new Error('需求正文不可用');return latest.source_snapshot_id}))}
async function openDelivery(id:string){try{if(localConnected.value){await localIde.value!.prepareSnapshot('submission');await syncLocal(workspaceId.value)}deliveryId.value=id;deliveryOpen.value=true}catch(e){ElMessage.error(String(e))}}
async function retryLocalPatch(id:string){patch.value=workspace.value?.actions.find(a=>a.id===id)??null;if(patch.value)await applyPatch()}

const plans=ref<Plan[]>([]),planId=ref(''),objectiveId=ref(''),units=ref<Unit[]>([]),unitId=ref(''),selections=ref<Selection[]>([])
const knowledgeDialog=ref(false),knowledgeLinks=ref<{link_id:string;citation_id:string;path:string;start_line:number;end_line:number;note:string}[]>([]),knowledgeProjects=ref<{repository_snapshot_id:string;name:string;commit:string;indexed:boolean}[]>([])
const referenceSnapshotId=ref(''),bindStart=ref(1),bindEnd=ref(10)
const mode=ref('reference'),citation=ref<Citation|null>(null),refFiles=ref<RepoFile[]>([]),refPath=ref(''),refText=ref(''),refStart=ref(1),refEnd=ref(1),refTotal=ref(1),highlight=ref<[number,number]>([0,0]),codeBox=ref<HTMLElement|null>(null)
const workspaces=ref<{workspace_id:string;name:string}[]>([]),workspace=ref<Workspace|null>(null),workspaceId=ref(''),filePath=ref(''),editor=ref(''),editorRef=ref<HTMLTextAreaElement|null>(null),gutter=ref<HTMLElement|null>(null)
const agentMode=ref<'learn'|'assist'>('learn'),knowledgeScope=ref<string[]>([]),modelCallLimit=ref(4)
const agentConfig=ref<{model:string;reasoning_effort:string;max_output_tokens:number}|null>(null)
const practiceId=ref(''),agentPaths=ref<string[]>([]),deliveryId=ref(''),deliveryOpen=ref(false)
const practices=computed(()=>workspace.value?.actions.filter(a=>a.kind==='practice'&&a.status!=='unavailable'&&a.objective_version_id===objectiveId.value)??[])
const selectedPractice=computed(()=>practices.value.find(a=>a.id===practiceId.value))
const independentWorkspace=computed(()=>workspace.value?.study_attempt?.help_mode==='independent')
const agentActive=computed(()=>workspace.value?.actions.some(a=>a.kind==='learning_run'&&['queued','running','waiting_user'].includes(a.status))??false)
const instruction=ref(''),runId=ref(''),busy=ref(false),planDialog=ref(false),patch=ref<Action|null>(null),command=ref('["python", "main.py"]'),fileFilter=ref(''),loadingReference=ref(false)
const selectedPlan=computed(()=>plans.value.find(p=>p.plan_id===planId.value))
const objective=computed(()=>selectedPlan.value?.objectives.find(o=>o.objective_version_id===objectiveId.value))
const relevantUnits=computed(()=>units.value.filter(u=>u.objective_version_id===objectiveId.value))
const unit=computed(()=>relevantUnits.value.find(u=>u.learning_unit_id===unitId.value)??relevantUnits.value[0])
const selection=computed(()=>selections.value.find(s=>s.selection_id===unit.value?.selection_id))
const ownFiles=computed(()=>Object.keys(workspace.value?.files??{}).sort().filter(p=>p.toLowerCase().includes(fileFilter.value.toLowerCase())))
const dirty=computed(()=>localConnected.value?!!localIde.value?.dirty:!!workspace.value&&!!filePath.value&&editor.value!==workspace.value.files[filePath.value])
const codeLines=computed(()=>refText.value.split('\n').map((text,i)=>({number:refStart.value+i,text})))
let navigation=0
async function all<T>(path:string):Promise<T[]>{let cursor:string|null=null;const rows:T[]=[];do{const p:{data:T[];next_cursor?:string|null}=await apiPage<T>(path+(path.includes('?')?'&':'?')+'limit=100'+(cursor?'&cursor='+cursor:''));rows.push(...p.data);cursor=p.next_cursor??null}while(cursor);return rows}
async function load(){try{requirementSources.value=(await all<{source_id:string;title:string|null;read_status:string;source_type:string}>('/sources')).filter(s=>s.read_status==='available');agentConfig.value=await api('/job-data/agent-config');[plans.value,units.value,selections.value,workspaces.value]=await Promise.all([all<Plan>('/plans'),all<Unit>('/learning-units'),all<Selection>('/project-selections'),api<{workspace_id:string;name:string}[]>('/studio/workspaces')]);if(!planId.value)planId.value=plans.value.find(p=>p.objectives.some(o=>o.objective_version_id===route.query.objective))?.plan_id??plans.value[0]?.plan_id??'';if(!objectiveId.value)objectiveId.value=selectedPlan.value?.objectives.find(o=>o.objective_version_id===route.query.objective)?.objective_version_id??selectedPlan.value?.objectives[0]?.objective_version_id??'';if(!workspace.value&&workspaces.value[0])await openWorkspace(workspaces.value[0].workspace_id);knowledgeProjects.value=await api('/knowledge/projects');await loadKnowledgeLinks();if(route.query.citation)await openCitation(String(route.query.citation));else if(!studyTrackId&&knowledgeLinks.value[0]&&!citation.value)await openCitation(knowledgeLinks.value[0].citation_id);else if(!studyTrackId&&unit.value&&!citation.value)await openStep(unit.value.reading_steps[0]);}catch(e){ElMessage.error(String(e))}}
async function canLeave(){if(!dirty.value&&!localIde.value?.pendingId)return true;try{await ElMessageBox.confirm(localIde.value?.pendingId?'本机补丁已写入，但后端记录尚未同步。离开会结束当前目录会话；可先重试保存应用记录。是否仍离开？':'当前文件有未保存修改，是否放弃这些修改？','切换文件',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'});return true}catch{return false}}
async function loadKnowledgeLinks(){knowledgeLinks.value=objectiveId.value?await api('/knowledge/links?objective_version_id='+objectiveId.value):[]}
async function openKnowledge(id:string){knowledgeDialog.value=false;await openCitation(id)}
async function removeKnowledgeLink(id:string){try{await write('/knowledge/links/'+id,'DELETE',{});await loadKnowledgeLinks()}catch(e){ElMessage.error(String(e))}}
async function chooseObjective(){practiceId.value='';agentPaths.value=[];await loadKnowledgeLinks();unitId.value='';citation.value=null;refText.value='';refFiles.value=[];const link=workspace.value?.links?.find(l=>l.objective_version_id===objectiveId.value);if(link)await openCitation(link.citation_id);else if(knowledgeLinks.value[0])await openCitation(knowledgeLinks.value[0].citation_id);else await openStep(unit.value?.reading_steps[0])}
async function choosePlan(){objectiveId.value=selectedPlan.value?.objectives[0]?.objective_version_id??'';await chooseObjective()}
async function openStep(step:Unit['reading_steps'][number]|undefined){if(!step?.citation_ids.length)return;await openCitation(step.citation_ids[0])}
async function openCitation(id:string){const token=++navigation;loadingReference.value=true;try{const c=await api<Citation>('/citations/'+id);if(token!==navigation)return;citation.value=c;referenceSnapshotId.value=c.repository_snapshot_id;refFiles.value=await all<RepoFile>('/repository-snapshots/'+c.repository_snapshot_id+'/files');if(token!==navigation)return;highlight.value=[c.start_line,c.end_line];mode.value='reference';await readReference(c.path,Math.max(1,c.start_line-15));}catch(e){ElMessage.error(String(e))}finally{if(token===navigation)loadingReference.value=false}}
async function readReference(path:string,start=1){if(!referenceSnapshotId.value&&!citation.value&&!selection.value)return;const snapshot=referenceSnapshotId.value||citation.value?.repository_snapshot_id||selection.value!.repository_snapshot_id;const f=refFiles.value.find(f=>f.path===path);refTotal.value=f?.line_count??Math.max(200,citation.value?.end_line??1);refStart.value=Math.max(1,Math.min(start,refTotal.value));refEnd.value=Math.min(refStart.value+199,refTotal.value);const r=await api<{content:string}>('/repository-snapshots/'+snapshot+'/file-content?path='+encodeURIComponent(path)+`&start_line=${refStart.value}&end_line=${refEnd.value}`);refPath.value=path;refText.value=r.content;await nextTick();codeBox.value?.querySelector('.selected-line')?.scrollIntoView({block:'center',behavior:'smooth'})}
async function chooseReference(){try{citation.value=null;highlight.value=[0,0];refFiles.value=await all<RepoFile>('/repository-snapshots/'+referenceSnapshotId.value+'/files');if(refFiles.value[0])await readReference(refFiles.value[0].path)}catch(e){ElMessage.error(String(e))}}
async function bindReference(){if(!workspace.value||!objectiveId.value||!referenceSnapshotId.value||!refPath.value)return;try{workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/reference-links','POST',{objective_version_id:objectiveId.value,repository_snapshot_id:referenceSnapshotId.value,path:refPath.value,start_line:bindStart.value,end_line:bindEnd.value});const link=workspace.value.links?.at(-1);if(link)await openCitation(link.citation_id);ElMessage.success('已绑定到当前学习目标，点击目标即可定位')}catch(e){ElMessage.error(String(e))}}
async function toggleStep(step:Unit['reading_steps'][number]){if(!unit.value)return;try{const ids=new Set(unit.value.progress.completed_step_ids);ids.has(step.step_id)?ids.delete(step.step_id):ids.add(step.step_id);await write('/learning-units/'+unit.value.learning_unit_id+'/progress','PATCH',{expected_version:unit.value.progress.version,completed_step_ids:[...ids],actual_minutes:unit.value.progress.actual_minutes??null,note:unit.value.progress.note??''});units.value=await all<Unit>('/learning-units')}catch(e){ElMessage.error(String(e))}}
async function openWorkspace(id:string,guard=true){if(guard&&!await canLeave())return;try{workspace.value=await api<Workspace>('/studio/workspaces/'+id);workspaceId.value=id;practiceId.value='';agentPaths.value=[];filePath.value=Object.keys(workspace.value.files).sort()[0]??'';editor.value=workspace.value.files[filePath.value]??'';const active=workspace.value.actions.find(a=>a.kind==='learning_run'&&['queued','running','waiting_user'].includes(a.status));runId.value=active?.run_id??''}catch(e){ElMessage.error(String(e))}}
async function openFile(name:string){if(!await canLeave())return;filePath.value=name;editor.value=workspace.value?.files[name]??'';mode.value='ide'}
async function newWorkspace(files:Record<string,string>={}){if(!await canLeave())return;try{const {value}=await ElMessageBox.prompt('为练习项目命名，代码作为独立副本保存。','创建自己的工作区',{inputValue:'我的学习项目'});workspace.value=await write<Workspace>('/studio/workspaces','POST',{name:value,files});workspaceId.value=workspace.value.workspace_id;practiceId.value='';agentPaths.value=[];filePath.value=Object.keys(files)[0]??'';editor.value=files[filePath.value]??'';mode.value='ide';workspaces.value=await api('/studio/workspaces')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(String(e))}}
async function importFolder(event:Event){const input=event.target as HTMLInputElement;const files:Record<string,string>={};let skipped=0;try{for(const file of Array.from(input.files??[])){const name=file.webkitRelativePath.split('/').slice(1).join('/')||file.name;if(name.split('/').some(x=>['.git','.env','.aws','.ssh','.codex','node_modules','.venv','__pycache__'].includes(x)||x.startsWith('.env.'))||file.size>100000||!(/\.(py|js|ts|tsx|jsx|vue|java|json|md|txt|toml|yaml|yml|html|css|sql|xml|properties|sh|gitignore)$/i.test(name))){skipped++;continue}files[name]=await file.text();if(Object.keys(files).length>100)throw new Error('请选择更小的项目目录，最多 100 个文本文件')}if(skipped)ElMessage.info(`已跳过 ${skipped} 个私密、依赖、二进制或过大文件`);if(Object.keys(files).length)await newWorkspace(files)}catch(e){ElMessage.error(String(e))}finally{input.value=''}}
async function newFile(){if(!workspace.value||!await canLeave())return;try{const {value}=await ElMessageBox.prompt('输入相对文件路径，例如 src/main.py','新建文件');if(value in workspace.value!.files)throw new Error('文件已存在');workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/file','PUT',{expected_revision:workspace.value.revision,path:value,content:''});filePath.value=value;editor.value='';mode.value='ide'}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(String(e))}}
async function save(){if(!workspace.value||!filePath.value)return;try{workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/file','PUT',{expected_revision:workspace.value.revision,path:filePath.value,content:editor.value});ElMessage.success('已保存工作区文件')}catch(e){ElMessage.error(String(e))}}
function exportWorkspace(){if(!workspace.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify({name:workspace.value.name,files:workspace.value.files},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=workspace.value.name+'.json';a.click();URL.revokeObjectURL(url)}
async function openLearningPoint(point:LearningPoint){await openCitation(point.citation_id);if(citation.value?.citation_id===point.citation_id){highlight.value=[point.quote_start_line,point.quote_end_line];await readReference(citation.value.path,Math.max(1,point.quote_start_line-12))}}
async function resumePractice(practice:Action){
  if(practice.origin==='study_module'){objectiveId.value=practice.objective_version_id!;practiceId.value=practice.id;agentPaths.value=filePath.value?[filePath.value]:[];agentMode.value='assist';mode.value='ide';return}
  const plan=plans.value.find(p=>p.objectives.some(o=>o.objective_version_id===practice.objective_version_id))
  if(!plan){ElMessage.warning('练习目标不在当前可用计划中，请先恢复或选择对应计划');return}
  usePlan.value=true;planId.value=plan.plan_id;objectiveId.value=practice.objective_version_id!;await chooseObjective()
  practiceId.value=practice.id;agentPaths.value=filePath.value?[filePath.value]:[];agentMode.value='assist';mode.value='ide'
  instruction.value='围绕当前迁移练习，先实现一个小步骤。说明引用依据和需要我验证的内容；补丁与命令均由我审阅确认。'
}
async function createPractice(report:Action,index:number){
  if(!workspace.value||busy.value)return
  if(!report.objective_version_id){
    const text=report.guide?.practice[index]??'';if(report.sources?.[0])await openCitation(report.sources[0].citation_id)
    instruction.value='基于刚才的学习说明和当前代码依据，实现这个小步骤：'+text;agentMode.value='assist';mode.value='ide';ElMessage.info('练习已带入 Agent 输入；发送后才调用模型');return
  }
  busy.value=true
  try{const r=await write<{workspace:Workspace;practice_id:string}>('/studio/workspaces/'+workspaceId.value+'/learning-reports/'+report.id+'/practices','POST',{expected_revision:workspace.value.revision,exercise_index:index});workspace.value=r.workspace;const practice=workspace.value.actions.find(a=>a.id===r.practice_id);if(practice)await resumePractice(practice);ElMessage.success('练习草稿已保存；点击发送才会调用 Agent')}
  catch(e){ElMessage.error(String(e))}finally{busy.value=false}
}
async function savePracticeNote(id:string,note:string){
  if(!workspace.value||busy.value)return
  busy.value=true
  try{workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/practices/'+id+'/note','PATCH',{expected_revision:workspace.value.revision,note});ElMessage.success('练习笔记已保存')}
  catch(e){ElMessage.error(String(e))}finally{busy.value=false}
}
async function ask(){
  if(!workspace.value||agentActive.value)return
  if(independentWorkspace.value){ElMessage.warning('独立工作区禁用 Agent，请本人编辑并提交，或另建辅助尝试');return}
  if(desktop&&storage.value==='local'&&agentMode.value==='assist'&&!localConnected.value){ElMessage.warning('请先打开本机项目，或切换到独立练习副本');return}
  if(agentMode.value==='learn'&&!(usePlan.value&&objectiveId.value)&&!sourceIds.value.length&&!incomingSources.value.length){ElMessage.warning('请选择人工导入的需求资料，或已有学习目标');return}
  if(agentMode.value==='assist'&&!instruction.value.trim())return
  if(agentMode.value==='assist'&&dirty.value){ElMessage.warning('请先保存代码，再让 Agent 分析');return}
  busy.value=true
  try{
    const learn=agentMode.value==='learn'
    let localPaths:string[]|null=null
    if(!learn&&localConnected.value){localPaths=(await localIde.value!.prepareSnapshot('agent')).paths;await syncLocal(workspaceId.value)}
    const sources=learn?await resolveSources():[]
    const r=await write<{run_id:string}>('/studio/workspaces/'+workspaceId.value+'/agent-runs','POST',{
      expected_revision:workspace.value.revision,mode:agentMode.value,
      instruction:(!learn&&studyModule.value?JSON.stringify({module:{title:studyModule.value.title,depth:studyModule.value.depth,steps:studyModule.value.steps.slice(0,3),deliverable:studyModule.value.deliverable,acceptance:studyModule.value.acceptance.slice(0,3)},user_request:instruction.value}):instruction.value).trim()||(learn?'根据当前学习目标自主查找相关代码，生成带原文依据的学习说明和小型迁移练习。':''),
      objective_version_id:learn?(sources.length||!usePlan.value?null:objectiveId.value||null):(selectedPractice.value||usePlan.value?objectiveId.value||null:null),source_snapshot_ids:sources,
      practice_id:!learn?selectedPractice.value?.id??null:null,
      citation_ids:!learn&&!selectedPractice.value&&citation.value?[citation.value.citation_id]:[],
      paths:!learn?(localPaths??(selectedPractice.value?agentPaths.value.filter(p=>p in workspace.value!.files):filePath.value?[filePath.value]:[])):[],
      knowledge_snapshot_ids:learn?knowledgeScope.value:[],model_call_limit:modelCallLimit.value
    });runId.value=r.run_id;instruction.value='';await progress()
  }catch(e){ElMessage.error(String(e))}finally{busy.value=false}
}
async function progress(){if(!workspaceId.value)return;try{const wasDirty=dirty.value||localConnected.value;const r=await api<Workspace>('/studio/workspaces/'+workspaceId.value);workspace.value=r;if(!wasDirty)editor.value=r.files[filePath.value]??''}catch(e){ElMessage.error(String(e))}}
async function applyPatch(){
  if(!workspace.value||!patch.value)return
  if(independentWorkspace.value&&!patch.value.command_id){ElMessage.warning('独立工作区不能应用 Agent 补丁');return}
  if(desktop&&storage.value==='local'&&!localConnected.value){ElMessage.warning('请先选择对应本机项目，或切换到独立练习副本');return}
  if(dirty.value){ElMessage.warning('请先保存当前文件');return}
  busy.value=true
  try{
    if(localConnected.value){
      const latest=await api<Workspace>('/studio/workspaces/'+workspaceId.value)
      const action=latest.actions.find(a=>a.id===patch.value!.id)
      if(!action||action.status==='unavailable'||!action.edits)throw new Error('补丁依据不可用')
      workspace.value=latest
      if(action.status!=='applied'){
        if(action.edits.some(e=>(latest.files[e.path]??null)!==e.before))throw new Error('后端快照已变化，请重新审阅')
        await localIde.value!.applyPatch(action.id,action.edits)
        workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/patches/'+action.id+'/apply','POST',{expected_revision:latest.revision,confirmation:'APPLY'})
      }
      localIde.value!.recorded();ElMessage.success('补丁已写入本机，应用记录已同步；没有执行命令')
    }else{
      workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/patches/'+patch.value.id+'/apply','POST',{expected_revision:workspace.value.revision,confirmation:'APPLY'});editor.value=workspace.value.files[filePath.value]??'';ElMessage.success('补丁已应用；尚未执行命令')
    }
    patch.value=null
  }catch(e){ElMessage.error(String(e))}finally{busy.value=false}
}
async function propose(){if(!workspace.value)return;try{const argv:unknown=JSON.parse(command.value);if(!Array.isArray(argv)||argv.some(x=>typeof x!=='string'))throw new Error('请输入 JSON 字符串数组');workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/commands','POST',{expected_revision:workspace.value.revision,argv,reason:'用户手动添加命令',practice_id:selectedPractice.value?.id??null})}catch(e){ElMessage.error(String(e))}}
async function execute(a:Action){if(!workspace.value)return;if(desktop&&storage.value==='local'&&!localConnected.value){ElMessage.warning('请先选择项目或切换到独立练习副本');return;}if(dirty.value){ElMessage.warning('请先保存代码');return}try{let scope='';if(localConnected.value){const snapshot=await localIde.value!.prepareSnapshot('command');scope='\n快照文件：'+snapshot.paths.join('、');await syncLocal(workspaceId.value)}await ElMessageBox.confirm(`工作区：${workspace.value.name}${scope}\n命令：${JSON.stringify(a.argv)}\n在无网络容器执行，最长 30 秒。生成文件仍需审阅应用。`,'确认执行此命令',{confirmButtonText:'确认执行',cancelButtonText:'取消',type:'warning'});busy.value=true;workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/commands/'+a.id+'/execute','POST',{expected_revision:workspace.value.revision,confirmation:'RUN'})}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(String(e));await progress()}finally{busy.value=false}}
function tab(event:KeyboardEvent){if(event.key!=='Tab')return;event.preventDefault();const e=event.target as HTMLTextAreaElement,start=e.selectionStart,end=e.selectionEnd;editor.value=editor.value.slice(0,start)+'  '+editor.value.slice(end);void nextTick(()=>{e.selectionStart=e.selectionEnd=start+2})}

const studyTrackId=typeof route.query.track==='string'?route.query.track:''
const studyData=ref<StudyTrack|null>(null),studyPlanId=ref(typeof route.query.study_plan==='string'?route.query.study_plan:''),studyModuleKey=ref('')
const studyPlan=computed(()=>studyData.value?.plans.find(p=>p.id===studyPlanId.value)??studyData.value?.plans.at(-1))
const studyModule=computed(()=>studyPlan.value?.modules.find(m=>m.key===studyModuleKey.value))
const studyHighlights=computed(()=>[...(studyData.value?.approved_projects.flatMap(p=>p.highlights)??[]),...(studyPlan.value?.focus_highlights??[])])
let studyLoadNo=0
async function loadStudy(){if(!studyTrackId)return;const n=++studyLoadNo;try{const data=await api<StudyTrack>('/study/tracks/'+studyTrackId);if(n!==studyLoadNo)return;studyData.value=data;if(!studyModuleKey.value)studyModuleKey.value=studyPlan.value?.modules.find(m=>!studyPlan.value?.modules.some(c=>c.parent_key===m.key))?.key??studyPlan.value?.modules[0]?.key??''}catch(e){studyData.value=null;ElMessage.error(String(e))}}
function moduleDepth(key:string){let depth=0,item=studyPlan.value?.modules.find(m=>m.key===key);while(item?.parent_key&&depth<3){depth++;item=studyPlan.value?.modules.find(m=>m.key===item?.parent_key)}return depth}
async function openStudyPoint(point:{citation_id:string;quote_start_line:number;quote_end_line:number}){await openCitation(point.citation_id);if(citation.value?.citation_id===point.citation_id){highlight.value=[point.quote_start_line,point.quote_end_line];await readReference(citation.value.path,Math.max(1,point.quote_start_line-12))}}
async function chooseStudyModule(key:string){studyModuleKey.value=key;const module=studyPlan.value?.modules.find(m=>m.key===key);if(module?.highlight_ids[0])await openCitation(module.highlight_ids[0])}
async function openModuleAttempt(value:{workspace_id:string;practice_id:string},delivery=false){
 if(!await canLeave())return
 await localIde.value?.disconnect();storage.value='copy';await openWorkspace(value.workspace_id,false)
 const practice=workspace.value?.actions.find(a=>a.id===value.practice_id)
 if(practice)await resumePractice(practice)
 if(delivery)await openDelivery(value.practice_id)
}
async function studyPlanUpdated(value:{kind:string;plan_id:string}){
 if(value.kind==='study'){studyPlanId.value=value.plan_id;await loadStudy()}else await load()
}
async function studyProgress(state:string){if(!studyData.value||!studyPlan.value||!studyModule.value)return;try{studyData.value=await api<StudyTrack>('/study/tracks/'+studyTrackId+'/progress','PUT',{expected_revision:studyData.value.revision,plan_id:studyPlan.value.id,module_key:studyModule.value.key,state});}catch(e){ElMessage.error(String(e))}}
watch(studyModule, module=>{if(module?.highlight_ids[0]&&!citation.value)void openCitation(module.highlight_ids[0])})
watch(mode,value=>{if(studyTrackId&&value==='ide')agentMode.value='assist'})

watch(()=>route.query.study_plan,value=>{if(typeof value==='string'&&value!==studyPlanId.value){studyPlanId.value=value;void loadStudy()}})

function beforeUnload(e:BeforeUnloadEvent){if(dirty.value||localIde.value?.pendingId){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(async()=>{const ok=await canLeave();if(ok)await localIde.value?.disconnect();return ok});onMounted(()=>{void loadStudy();void load();window.addEventListener('beforeunload',beforeUnload)});onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
</script>
<template>
<section class="page-heading"><div><h1>{{studyTrackId?"学习与实践":"学习 IDE"}}</h1><p>{{studyPlan?.title??"阅读参考代码，在自己的项目中编辑并审阅 Agent 补丁。"}}</p><router-link to="/agent">← Agent 工作台</router-link></div><el-button @click="load">刷新</el-button></section>
<div class="studio-grid" :class="{'modular-study':!!studyTrackId}">
<aside v-if="studyTrackId" class="studio-pane plan-pane study-plan-pane"><h2>模块化学习计划</h2><el-select v-if="studyData?.plans.length" v-model="studyPlanId" @change="studyModuleKey='';loadStudy()"><el-option v-for="p in studyData.plans" :key="p.id" :value="p.id" :label="p.title"/></el-select><p v-if="studyPlan">{{studyPlan.summary}}</p><el-empty v-if="!studyPlan" description="计划不可用，请返回工作台检查需求和审核项目。"/><button v-for="m in studyPlan?.modules" :key="m.key" class="objective" :class="{active:studyModuleKey===m.key}" :style="{paddingLeft:(8+moduleDepth(m.key)*16)+'px'}" @click="chooseStudyModule(m.key)"><small>{{m.depth}} · 第 {{moduleDepth(m.key)+1}} 级</small><br>{{m.title}}</button><template v-if="studyModule"><h3>学习步骤</h3><ol><li v-for="s in studyModule.steps" :key="s">{{s}}</li></ol><h3>技术亮点索引</h3><div v-for="id in studyModule.highlight_ids" :key="id"><el-button link @click="openCitation(id)">{{studyHighlights.find(h=>h.citation_id===id)?.path??'核心实现'}}:{{studyHighlights.find(h=>h.citation_id===id)?.start_line}}</el-button></div><h3>本模块成果</h3><p>{{studyModule.deliverable}}</p><ul><li v-for="s in studyModule.acceptance" :key="s">{{s}}</li></ul><el-select :model-value="studyData?.progress[(studyPlan?.id??'')+':'+studyModule.key]?.state??'pending'" @change="studyProgress"><el-option label="待学习" value="pending"/><el-option label="学习中" value="learning"/><el-option label="已完成（本人记录）" value="completed"/></el-select><small class="muted">学习进度由你记录，不代表职业能力正式验收。</small><StudyPracticePanel v-if="studyData&&studyPlan" :track="studyData" :plan="studyPlan" :module="studyModule" @open="openModuleAttempt" @delivery="value=>openModuleAttempt(value,true)" @changed="loadStudy"/></template><el-button link @click="mode='ide';instruction='根据当前模块的目标和参考代码，帮我实现一个可审阅的小步骤。'">转入自己的 IDE 实践</el-button></aside>
<aside v-else class="studio-pane plan-pane"><h2>需求资料</h2><el-select v-model="sourceIds" multiple :multiple-limit="3" clearable placeholder="选择人工导入的岗位 / 技术资料" @change="incomingSources=[]"><el-option v-for="source in requirementSources" :key="source.source_id" :value="source.source_id" :label="source.title||'未命名资料'"/></el-select><p v-if="incomingSources.length" class="muted">已带入 {{incomingSources.length}} 份固定版本正文。</p><router-link to="/sources">导入或管理需求资料 →</router-link><h3>开源项目</h3><el-select v-model="knowledgeScope" multiple clearable placeholder="留空使用已导入项目"><el-option v-for="p in knowledgeProjects.filter(p=>p.indexed)" :key="p.repository_snapshot_id" :value="p.repository_snapshot_id" :label="p.name"/></el-select><router-link to="/knowledge">导入或管理开源项目 →</router-link><details class="study-details"><summary>已有学习计划与代码关联</summary><el-checkbox v-model="usePlan">使用已有计划目标作为本次需求</el-checkbox><h3>学习计划</h3><el-select v-model="planId" placeholder="选择已有计划" @change="choosePlan"><el-option v-for="p in plans" :key="p.plan_id" :value="p.plan_id" :label="`计划 v${p.version} · ${p.kind} · ${p.plan_id.slice(0,6)}`"/></el-select><el-button link @click="planDialog=true">在此编辑已有计划</el-button><el-empty v-if="!plans.length" description="先创建或导入学习计划"/><button v-for="o in selectedPlan?.objectives" :key="o.objective_version_id" class="objective" :class="{active:o.objective_version_id===objectiveId}" @click="objectiveId=o.objective_version_id;chooseObjective()">{{o.title}}</button><template v-if="objective"><p>{{objective.target_behavior}}</p><small v-for="d in objective.deliverables" :key="d" class="deliverable">交付物：{{d}}</small></template><el-button type="primary" plain @click="knowledgeDialog=true">为当前目标检索代码</el-button><h3>知识库关联</h3><div v-for="l in knowledgeLinks" :key="l.link_id"><el-button link @click="openCitation(l.citation_id)">{{l.path}}:{{l.start_line}}–{{l.end_line}}</el-button><small v-if="l.note" class="muted">{{l.note}}</small><el-button link @click="removeKnowledgeLink(l.link_id)">移除关联</el-button></div><h3>手动绑定的代码定位</h3><el-button v-for="l in workspace?.links?.filter(l=>l.objective_version_id===objectiveId)" :key="l.citation_id" link @click="openCitation(l.citation_id)">{{l.path}}:{{l.start_line}}–{{l.end_line}}</el-button><h3>代码阅读步骤</h3><el-select v-if="relevantUnits.length>1" v-model="unitId" @change="openStep(unit?.reading_steps[0])"><el-option v-for="u in relevantUnits" :key="u.learning_unit_id" :value="u.learning_unit_id" :label="u.why_this_unit"/></el-select><div v-for="s in unit?.reading_steps" :key="s.step_id" class="step"><el-checkbox :model-value="unit?.progress.completed_step_ids.includes(s.step_id)" @change="toggleStep(s)">已阅读</el-checkbox><button @click="openStep(s)">{{s.title}}</button><p>{{s.why}}</p><el-button v-for="(id,i) in s.citation_ids" :key="id" link @click="openCitation(id)">定位代码 {{i+1}}</el-button></div><p v-if="!unit">此目标尚无绑定的代码阅读单元。</p><el-button @click="router.push('/projects')">选择参考项目 / 生成阅读单元</el-button><small class="muted">阅读勾选只记录进度，不代表已掌握。未绑定的目标不会猜测代码位置。</small></details></aside>
<section class="studio-pane code-pane"><div class="mode-bar"><el-radio-group v-model="mode"><el-radio-button value="reference">开源参考代码</el-radio-button><el-radio-button value="ide">自己的 IDE</el-radio-button></el-radio-group></div>
<template v-if="mode==='reference'"><div class="code-toolbar"><el-select v-model="referenceSnapshotId" placeholder="选择已保存的参考项目版本" @change="chooseReference"><el-option v-for="p in knowledgeProjects" :key="p.repository_snapshot_id" :value="p.repository_snapshot_id" :label="p.name+' · '+p.commit.slice(0,8)"/></el-select></div><div class="code-toolbar"><el-select v-model="refPath" filterable placeholder="参考文件" @change="readReference(refPath)"><el-option v-for="f in refFiles" :key="f.path" :label="f.path" :value="f.path"/></el-select><el-tag>只读固定版本</el-tag></div><p v-if="citation" class="muted">{{citation.commit}} · 高亮 {{highlight[0]}}–{{highlight[1]}} 行</p><div v-if="refPath&&workspace&&objectiveId" class="code-toolbar"><span>绑定行范围</span><el-input-number v-model="bindStart" :min="1" :max="refTotal" size="small"/><el-input-number v-model="bindEnd" :min="bindStart" :max="Math.min(refTotal,bindStart+199)" size="small"/><el-button @click="bindReference">绑定到当前目标</el-button></div><div ref="codeBox" v-loading="loadingReference" class="reference-code"><div v-for="line in codeLines" :key="line.number" class="code-line" :class="{'selected-line':refPath===citation?.path&&line.number>=highlight[0]&&line.number<=highlight[1]}"><span>{{line.number}}</span><code>{{line.text || ' '}}</code></div><el-empty v-if="!refText" description="点击左侧阅读步骤或代码引用"/></div><div class="code-toolbar"><el-button :disabled="refStart<=1" @click="readReference(refPath,Math.max(1,refStart-200))">前 200 行</el-button><span>{{refStart}}–{{refEnd}} / {{refTotal}}</span><el-button :disabled="refEnd>=refTotal" @click="readReference(refPath,refEnd+1)">后 200 行</el-button></div></template>
<template v-else><div v-if="desktop" class="code-toolbar"><el-radio-group :model-value="storage" @change="switchStorage"><el-radio-button value="local">本机项目</el-radio-button><el-radio-button value="copy">独立练习副本</el-radio-button></el-radio-group></div><div v-show="storage==='copy'"><div class="code-toolbar"><el-select :model-value="workspaceId" placeholder="自己的工作区" @change="openWorkspace"><el-option v-for="w in workspaces" :key="w.workspace_id" :value="w.workspace_id" :label="w.name"/></el-select><el-button @click="newWorkspace()">新工作区</el-button><label class="import-button">导入目录副本<input type="file" webkitdirectory multiple @change="importFolder"/></label></div><small class="muted">保存到 CareerForge 的独立代码副本，原目录保持不变。最多 100 个文本文件 / 2 MB。</small><div v-if="workspace" class="ide"><aside class="file-tree"><el-input v-model="fileFilter" placeholder="查找文件"/><el-button link @click="newFile">＋ 文件</el-button><button v-for="name in ownFiles" :key="name" :class="{active:name===filePath}" @click="openFile(name)">{{name}}</button></aside><div class="editor-panel"><div class="code-toolbar"><span>{{filePath || '选择或创建文件'}}{{dirty?' ●':''}}</span><el-button type="primary" :disabled="!filePath||!dirty" @click="save">保存</el-button></div><div class="text-editor"><pre ref="gutter" class="line-gutter">{{editor.split('\n').map((_,i)=>i+1).join('\n')}}</pre><textarea ref="editorRef" v-model="editor" :disabled="!filePath" spellcheck="false" aria-label="项目代码编辑器" @keydown="tab" @keydown.ctrl.s.prevent="save" @keydown.meta.s.prevent="save" @scroll="gutter&&(gutter.scrollTop=editorRef?.scrollTop??0)"/></div></div></div><el-button v-if="workspace" link @click="exportWorkspace">导出工作区文件 JSON</el-button><div v-if="workspace" class="command-bar"><h3>待确认命令</h3><el-input v-model="command" placeholder='["python", "main.py"]'/><el-button @click="propose">添加待执行命令</el-button><small class="muted">Python 运行环境，无网络；Node/npm 需另配对应运行镜像，当前不会自动下载依赖。</small></div></div></template>
<LocalProjectIde v-if="desktop" v-show="mode==='ide'&&storage==='local'" ref="localIde" :workspace="workspace" :can-switch="canLeave" :practice-bound="!!workspace?.study_attempt" :independent="independentWorkspace" @bound="bindLocal" @synced="syncLocal" @retry="retryLocalPatch"/>
<div v-if="mode==='ide'&&localConnected" class="command-bar"><h3>待确认命令</h3><el-input v-model="command" placeholder='["python","main.py"]'/><el-button @click="propose">添加命令建议</el-button><small class="muted">只在现有无网络沙箱运行所选文件副本，执行前仍需确认。</small></div>
</section>
<aside v-if="studyData&&studyPlan&&studyModule&&mode==='reference'" class="studio-pane agent-pane"><StudyTutor :key="studyPlan.id+studyModule.key" :track="studyData" :plan="studyPlan" :module="studyModule" @changed="loadStudy" @open="openCitation" @point="openStudyPoint"/></aside>
<aside v-else class="studio-pane agent-pane"><h2>项目 Agent</h2><el-radio-group v-model="agentMode"><el-radio-button value="learn">学习说明 · 自主检索</el-radio-button><el-radio-button value="assist">代码补丁助手</el-radio-button></el-radio-group><p class="muted">{{agentConfig?.model ?? '读取配置中'}} · {{agentConfig?.reasoning_effort ?? 'low'}} · 每次最多 {{agentConfig?.max_output_tokens ?? '读取中'}} 输出 token。只有点击发送才调用模型。</p><details v-if="agentMode==='learn'"><summary>本次调用预算</summary><div class="code-toolbar"><span>模型调用上限</span><el-select v-model="modelCallLimit" style="max-width:130px"><el-option v-for="n in [2,3,4]" :key="n" :value="n" :label="n+' 次'"/></el-select></div><small class="muted">最多 8 次只读检索操作；不会联网采集需求。供应商金额未定价。</small></details><template v-if="agentMode==='assist'&&practices.length&&!localConnected"><el-select v-model="practiceId" clearable placeholder="选择已有练习（可选）"><el-option v-for="p in practices" :key="p.id" :value="p.id" :label="p.exercise?.slice(0,60)"/></el-select><template v-if="selectedPractice"><p class="context-pill">当前迁移练习：{{selectedPractice.exercise}}</p><el-select v-model="agentPaths" multiple :multiple-limit="3" clearable placeholder="发给 Agent 的已保存文件（最多 3 个）"><el-option v-for="name in Object.keys(workspace?.files??{}).sort()" :key="name" :value="name" :label="name"/></el-select><small class="muted">自动带入此练习的目标和代码依据。这里只发送所选文件的已保存内容。</small></template></template><p class="context-pill">{{agentMode==='learn' ?'上下文：人工导入的需求正文或已有目标 + 所选开源版本。Agent 分析需求并检索代码，不采集新需求，也不发送 IDE 文件。':selectedPractice?'上下文：所选练习 + 原学习目标与代码依据 + 所选已保存文件（最多 1 次模型调用）':'上下文：当前目标 + 当前参考代码引用 + 已保存的当前项目文件 + 最近 4 条工作记录（最多 1 次模型调用）'}}</p><el-button v-if="!workspace" @click="newWorkspace()">创建学习会话</el-button><el-alert v-if="!workspace" title="先创建一个学习会话，或在自己的 IDE 中打开项目。" type="info" :closable="false"/><details :open="!!runId"><summary>本会话学习与实践记录</summary><div class="conversation"><article v-for="a in workspace?.actions" :key="a.id" class="action"><LearningExplanation v-if="a.kind==='learning_report'||a.kind==='learning_run'" :report="a" @open="openCitation" @point="openLearningPoint" @run="id=>runId=id" @practice="index=>createPractice(a,index)"/><PracticeCard v-else-if="a.kind==='practice'" :practice="a" :actions="workspace?.actions??[]" :selected="selectedPractice?.id===a.id" :busy="busy" @resume="resumePractice(a)" @save="note=>savePracticeNote(a.id,note)" @open="openCitation" @delivery="openDelivery(a.id)"/><el-alert v-else-if="a.status==='unavailable'" title="此练习的依据已不可用，相关输出已隐藏。" type="warning" :closable="false"/><template v-else-if="a.kind==='message'"><p class="user-message">{{a.instruction}}</p><p class="agent-answer">{{a.answer}}</p><el-button v-for="id in a.citation_ids" :key="id" link @click="openCitation(id)">查看代码依据</el-button><small v-if="a.usage" class="muted">token {{a.usage.input_tokens}} / {{a.usage.output_tokens}}</small></template><template v-else-if="a.kind==='patch'"><strong>代码变更 · {{a.status==='applied'?'已应用':'待审阅'}}</strong><p>{{a.edits?.map(e=>e.path).join('、')}}</p><el-button :disabled="a.status==='applied'" @click="patch=a">审阅补丁</el-button></template><template v-else-if="a.kind==='command'"><strong>命令 · {{a.status}}</strong><pre>{{JSON.stringify(a.argv)}}</pre><p>{{a.reason}}</p><el-button v-if="a.status==='pending'" :loading="busy" @click="execute(a)">确认后执行</el-button><p v-if="a.exit_code!==undefined">退出码 {{a.exit_code}}（仅代表本命令结果）</p><pre v-if="a.stdout||a.stderr">{{a.stdout}}{{a.stderr}}</pre><el-alert v-if="a.error" :title="a.error" type="warning" :closable="false"/></template></article></div></details><RunPanel v-if="runId" :key="runId" :run-id="runId" @changed="progress"/><el-input v-model="instruction" type="textarea" :rows="4"  :placeholder="agentMode==='learn'?'可留空：根据当前学习目标自主检索；也可补充你希望重点理解的机制…':'解释当前参考代码，并帮我在自己的项目里实现一个小步骤…'"/><el-button type="primary" :disabled="independentWorkspace||!workspace||agentActive||(agentMode==='learn'?(!(usePlan&&objectiveId)&&!sourceIds.length&&!incomingSources.length):!instruction.trim())" :loading="busy" @click="ask">{{agentActive?'学习说明生成中':agentMode==='learn'?'检索并生成学习说明':'发送给 Agent'}}</el-button><small class="muted">补丁应用与命令执行不会自动将学习目标标记为完成。</small></aside>
</div>
<el-drawer v-model="deliveryOpen" title="练习成果与人工验收" size="min(1150px,96vw)" @closed="progress();loadStudy()"><PracticeDelivery v-if="deliveryOpen" :key="deliveryId" :workspace-id="workspaceId" :practice-id="deliveryId" @changed="progress" @plan="studyPlanUpdated"/></el-drawer>
<el-drawer v-model="knowledgeDialog" title="从代码学习库关联到当前目标" size="min(1200px,96vw)"><KnowledgeSearch v-if="knowledgeDialog" :objective-id="objectiveId" :objective-title="objective?.title" @open="openKnowledge" @bound="loadKnowledgeLinks"/><el-button link @click="router.push('/knowledge')">管理或导入开源项目</el-button></el-drawer>
<el-drawer v-model="planDialog" title="编辑已有学习计划" size="min(1100px,95vw)" @closed="load"><PlanningView v-if="planDialog"/></el-drawer>
